public int findLargestSubstring(List<String> strings) {
    Set<String> substrings = new HashSet<>();
    Set<String> inverseSubstrings = new HashSet<>();

    for (String str : strings) {
        for (int i = 0; i <= str.length(); i++) {
            for (int j = i + 1; j <= str.length(); j++) {
                String substring = str.substring(i, j);
                substrings.add(substring);
                inverseSubstrings.add(new StringBuilder(substring).reverse().toString());
            }
        }
    }

    int maxLength = 0;
    for (String substring : substrings) {
        if (inverseSubstrings.contains(substring) || inverseSubstrings.contains(new StringBuilder(substring).reverse().toString())) {
            maxLength = Math.max(maxLength, substring.length());
        }
    }

    return maxLength;
}
