public int findLargestSubstring(List<String> strings) {
    int maxLength = 0;

    for (String s : strings) {
        Set<String> substrings = findAllSubstrings(s);
        for (String sub : substrings) {
            if (isInverseSubstring(sub, strings)) {
                maxLength = Math.max(maxLength, sub.length());
            }
        }
    }

    return maxLength;
}

private Set<String> findAllSubstrings(String s) {
    Set<String> substrings = new HashSet<>();
    for (int i = 0; i < s.length(); i++) {
        for (int j = i + 1; j <= s.length(); j++) {
            substrings.add(s.substring(i, j));
        }
    }
    return substrings;
}

private boolean isInverseSubstring(String s, List<String> strings) {
    String reversed = new StringBuilder(s).reverse().toString();
    for (String str : strings) {
        if (str.contains(s) || str.contains(reversed)) {
            return true;
        }
    }
    return false;
}
