import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class SubstringFinder {

    /**
     * Finds the largest string X such that either X or its inverse can be found as a substring of any of the given strings.
     *
     * @param strings the list of case-sensitive strings to be processed
     * @return the length of the largest string X that meets the criteria
     */
    public int findLargestSubstring(List<String> strings) {
        Set<String> substrings = new HashSet<>();
        Set<String> reversedSubstrings = new HashSet<>();

        for (String str : strings) {
            for (int i = 1; i <= str.length(); i++) {
                String substring = str.substring(0, i);
                String reversedSubstring = new StringBuilder(substring).reverse().toString();
                substrings.add(substring);
                reversedSubstrings.add(reversedSubstring);
            }
        }

        int maxLength = 0;
        for (String s : substrings) {
            if (reversedSubstrings.contains(s) && s.length() > maxLength) {
                maxLength = s.length();
            }
        }

        return maxLength;
    }

    // Test cases to verify the solution correctness
    public static void main(String[] args) {
        SubstringFinder finder = new SubstringFinder();
        System.out.println(finder.findLargestSubstring(Arrays.asList("ABCD", "BCDFF", "BRCD"))); // Output: 2
        System.out.println(finder.findLargestSubstring(Arrays.asList("rose", "orchid"))); // Output: 2
    }
}
