public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("N must be a non-negative integer");
    }

    // Base cases
    if (N == 0) {
        return 1; // No triangles, plane is undivided
    }
    if (N == 1) {
        return 2; // One triangle divides the plane into 2 regions
    }

    // General case: each new triangle intersects all existing regions, adding 2N new regions
    return 1 + N + N * (N - 1) / 2;
}

