import java.util.List;

public class PrefixCounter {
    /**
     * Counts the number of words in the given word list that have the given prefix.
     *
     * @param wordList The list of words to be checked.
     * @param prefix The prefix string to be matched.
     * @return The number of words that start with the given prefix.
     */
    public static int countPrefixWords(List<String> wordList, String prefix) {
        if (wordList == null || prefix == null) {
            throw new IllegalArgumentException("Word list and prefix cannot be null");
        }

        int count = 0;
        for (String word : wordList) {
            if (word.startsWith(prefix)) {
                count++;
            }
        }
        return count;
    }

    // Test cases to verify the solution correctness
    public static void main(String[] args) {
