public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if start and end are the same
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    // Create a graph representation using an adjacency list
    List<Integer>[] graph = new ArrayList[n * n];
    for (int i = 0; i < graph.length; i++) {
        graph[i] = new ArrayList<>();
    }

    // Add edges to the graph
    for (int[] path : paths) {
        int u = path[0] * n + path[1];
        int v = path[2] * n + path[3];
        graph[u].add(v);
        graph[v].add(u);
    }

    // Create a visited array to keep track of visited nodes
    boolean[] visited = new boolean[n * n];

    // Helper function to perform DFS
    boolean dfs(int current, int endNode) {
        if (current == endNode) {
            return true;
        }
        visited[current] = true;
        for (int neighbor : graph[current]) {
            if (!visited[neighbor] && dfs(neighbor, endNode)) {
                return true;
            }
        }
        return false;
    }

    // Get the starting and ending node indices
    int startNode = start[0] * n + start[1];
    int endNode = end[0] * n + end[1];

    // Perform DFS to determine if there is a path from start to end
    if (dfs(startNode, endNode)) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}
