}

private static boolean hasPath(int x, int y, int endX, int endY, int[][] paths, boolean[][] visited) {
    if (x < 0 || x >= paths.length || y < 0 || y >= paths[0].length || visited[x][y] || paths[x][y] != 1) {
        return false;
    }
    if (x == endX && y == endY) {
        return true;
    }
    visited[x][y] = true;
    return hasPath(x + 1, y, endX, endY, paths, visited) ||
           hasPath(x - 1, y, endX, endY, paths, visited) ||
           hasPath(x, y + 1, endX, endY, paths, visited) ||
           hasPath(x, y - 1, endX, endY, paths, visited);
}

