public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create an adjacency list to represent the graph
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }

    // Populate the adjacency list with the given paths
    for (int[] path : paths) {
        int a = path[0];
        int b = path[1];
        graph[a].add(b);
        graph[b].add(a);
    }

    // Create a visited array to keep track of visited n-tersections
    boolean[] visited = new boolean[n];

    // Helper method to perform DFS
    if (!dfs(graph, visited, start[0], end[0])) {
        return "cannot be travelled";
    }

    return "can be travelled";
}

// Depth-First Search method
private static boolean dfs(List<Integer>[] graph, boolean[] visited, int current, int target) {
    // If the current n-tersection is the target, return true
    if (current == target) {
        return true;
    }

    // Mark the current n-tersection as visited
    visited[current] = true;

    // Visit all adjacent n-tersections
    for (int neighbor : graph[current]) {
        if (!visited[neighbor]) {
            if (dfs(graph, visited, neighbor, target)) {
                return true;
            }
        }
    }

    // If no path found, return false
    return false;
}
