    boolean[][] visited = new boolean[n][n];
    boolean[] path = new boolean[n * n];

    if (!dfs(n, start, end, paths, visited, path, 0)) {
        return "cannot be travelled";
    }
    return "can be travelled";
}

private static boolean dfs(int n, int[] current, int[] end, int[][] paths, boolean[][] visited, boolean[] path, int index) {
    int x = current[0];
    int y = current[1];

    if (x == end[0] && y == end[1]) {
        return true;
    }

    if (x < 0 || x >= n || y < 0 || y >= n || visited[x][y] || path[index]) {
        return false;
    }

    visited[x][y] = true;
    path[index] = true;

    for (int[] neighbor : paths) {
        if ((neighbor[0] == x && neighbor[1] == y) || (neighbor[0] == end[0] && neighbor[1] == end[1])) {
            if (dfs(n, neighbor, end, paths, visited, path, index + 1)) {
                return true;
            }
        }
    }

    visited[x][y] = false;
    path[index] = false;
    return false;
}
