private static boolean hasPath(int n, int current, int target, int[][] paths, boolean[] visited) {
    if (current == target) {
        return true;
    }
    visited[current] = true;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 2; j++) {
            if (!visited[i] && paths[i][j] == current) {
                if (hasPath(n, i, target, paths, visited)) {
                    return true;
                }
            }
        }
    }
    return false;
}
