public double trimMean(int[] arr) {
    int n = arr.length;
    int elementsToTrim = (int) (n * 0.05);
    Arrays.sort(arr);
    double sum = 0;
    for (int i = elementsToTrim; i < n - elementsToTrim; i++) {
        sum += arr[i];
    }
    return sum / (n - 2 * elementsToTrim);
}
