public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<List<Integer>> adj = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        adj.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        adj.get(edge[0]).add(edge[1]);
        adj.get(edge[1]).add(edge[0]);
    }
    boolean[] visited = new boolean[n];
    return dfs(0, adj, hasApple, visited) * 2;
}

private int dfs(int node, List<List<Integer>> adj, boolean[] hasApple, boolean[] visited) {
    if (visited[node]) {
        return 0;
    }
    visited[node] = true;
    int time = 0;
    for (int neighbor : adj.get(node)) {
        time += dfs(neighbor, adj, hasApple, visited);
    }
    if ((node != 0 || time > 0) && hasApple[node]) {
        time += 2;
    }
    return time;
}
