class Solution {
    public int minTime(int n, int[][] edges, boolean[] hasApple) {
        List<Integer>[] graph = new List[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] edge : edges) {
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0]);
        }
        return dfs(0, 0, graph, hasApple)[1];
    }

    private int[] dfs(int node, int parent, List<Integer>[] graph, boolean[] hasApple) {
        int totalTime = 0, childrenTime = 0;
        for (int neighbor : graph[node]) {
            if (neighbor != parent) {
                int[] result = dfs(neighbor, node, graph, hasApple);
                childrenTime += result[0];
                totalTime += result[1];
            }
        }
        if (childrenTime == 0) {
            totalTime += hasApple[node] ? 2 : 0;
        } else {
            totalTime += 2;
        }
        return new int[]{childrenTime, totalTime == 0 ? 0 : totalTime};
    }
}
