public boolean splitArraySameAverage(int[] A) {
    int n = A.length;
    if (n <= 1) return false;

    int sum = 0;
    for (int num : A) sum += num;

    boolean[] dp = new boolean[sum + 1];
    dp[0] = true;

    for (int num : A) {
        for (int j = sum; j >= num; j--) {
            dp[j] = dp[j] || dp[j - num];
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        int target = i * sum / n;
        if (target * n != sum * i) continue;
        if (dp[target]) return true;
    }

    return false;
}
