public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) {
        return false;
    }

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[][] possible = new boolean[n + 1][sum + 1];
    possible[0][0] = true;

    for (int i = 1; i <= n; i++) {
        for (int j = 0; j <= sum; j++) {
            possible[i][j] = possible[i - 1][j];
            if (j >= nums[i - 1]) {
                possible[i][j] |= possible[i - 1][j - nums[i - 1]];
            }
        }
    }

    for (int i = 1; i < n; i++) {
        for (int j = i; j <= sum; j++) {
            if (possible[i][j] && possible[n - i][sum - j] && (sum * i) % n == 0 && (sum * (n - i)) % (n - i) == 0) {
                return true;
            }
        }
    }

    return false;
}
