    for (int i = 1; i <= n; i++) {
        int num = nums[i - 1];
        for (int j = n * sum; j >= num; j--) {
            dp[i][j] = dp[i - 1][j] || dp[i - 1][j - num];
        }
    }

    for (int i = 1; i <= n - 1; i++) {
        for (int j = 1; j <= n * sum // half of the total sum
             && j * i <= (n - i) * (n * sum - j); j++) { // to ensure both parts are non-empty
            if (dp[i][j] && (sum * i == j * (n - i))) {
                return true;
            }
        }
    }

    return false;
