public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) {
        return false;
    }

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[][] dp = new boolean[n + 1][sum + 1];
    dp[0][0] = true;

    for (int i = 1; i <= n; i++) {
        int num = nums[i - 1];
        for (int j = sum; j >= num; j--) {
            for (int k = i - 1; k >= 0; k--) {
                dp[k][j] = dp[k][j] || (dp[k - 1][j - num]);
            }
        }
    }

    double avg = (double) sum / n;
    for (int size = 1; size < n; size++) {
        if (size * avg == sum * size) {
            continue;
        }
        for (int j = sum; j >= 0; j--) {
            if (dp[size][j] && (sum - j) * size == (sum * size - j * size)) {
                return true;
            }
        }
    }

    return false;
}
