public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int remainingValue = k;
    int remainingChars = n;

    while (remainingChars > 0) {
        int maxPossibleValue = Math.min(25 * remainingChars, remainingValue);
        int currentCharValue = maxPossibleValue - 25 * (remainingChars - 1);
        result.append((char) ('a' + currentCharValue - 1));
        remainingValue -= currentCharValue;
        remainingChars--;
    }

    return result.toString();
}

public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a'; // Initialize with 'a' to minimize the string
        k -= 1; // Subtract the value of 'a' (1) from k
    }
    while (k > 0) {
        for (int i = n - 1; i >= 0; i--) {
            if (k >= 25) {
                result[i] = (char) ('a' + 25); // Set to 'z'
                k -= 25;
            } else {
                result[i] = (char) ('a' + k); // Set to the character with value k
                k = 0;
                break;
            }
        }
    }
    return new String(result);
}

