public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> steppingNumbers = new ArrayList<>();

    // Helper function to generate stepping numbers starting from a given number
    void generateSteppingNumbers(int num) {
        if (num > high) {
            return;
        }
        if (num >= low) {
            steppingNumbers.add(num);
        }
        int lastDigit = num % 10;
        if (lastDigit > 0) {
            generateSteppingNumbers(num * 10 + lastDigit - 1);
        }
        if (lastDigit < 9) {
            generateSteppingNumbers(num * 10 + lastDigit + 1);
        }
    }

    // Start generating stepping numbers from each digit from 0 to 9
    for (int i = 0; i <= 9; i++) {
        generateSteppingNumbers(i);
    }

    // Sort the list in ascending order
    steppingNumbers.sort(Integer::compareTo);
    return steppingNumbers;
}
