public class DigitCounter {
    public static int countDigitOne(int n) {
        if (n < 1) {
            return 0;
        }

        int count = 0;
        int factor = 1;
        int high = n, cur = 0, low = 0;

        while (high != 0 || cur != 0) {
            high = n / (factor * 10);
            cur = (n / factor) % 10;
            low = n - (n / factor) * factor;

            if (cur == 0) {
                count += high * factor;
            } else if (cur == 1) {
                count += high * factor + low + 1;
            } else {
                count += (high + 1) * factor;
            }

            factor *= 10;
        }

        return count;
    }

    // Test cases to verify the solution correctness
    public static void main(String[] args) {
        System.out.println(countDigitOne(13)); // Output: 6
        System.out.println(countDigitOne(0));  // Output: 0
        System.out.println(countDigitOne(100)); // Output: 21
        System.out.println(countDigitOne(213)); // Output: 52
    }
}
