        if (mat == null || mat.length == 0 || mat[0].length == 0) {
            return 0;
        }

        int m = mat.length;
        int n = mat[0].length;
        int longest = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (mat[i][j] == 1) {
                    int length = 0;
                    length = Math.max(length, horizontalLine(mat, i, j, m, n));
                    length = Math.max(length, verticalLine(mat, i, j, m, n));
                    length = Math.max(length, diagonalLine(mat, i, j, m, n));
                    length = Math.max(length, antiDiagonalLine(mat, i, j, m, n));
                    longest = Math.max(longest, length);
                }
            }
        }

        return longest;
    }

    private static int horizontalLine(int[][] mat, int i, int j, int m, int n) {
        int count = 0;
        while (j < n && mat[i][j] == 1) {
            count++;
            j++;
        }
        return count;
    }

    private static int verticalLine(int[][] mat, int i, int j, int m, int n) {
        int count = 0;
        while (i < m && mat[i][j] == 1) {
            count++;
            i++;
        }
        return count;
    }

    private static int diagonalLine(int[][] mat, int i, int j, int m, int n) {
        int count = 0;
        while (i < m && j < n && mat[i][j] == 1) {
            count++;
            i++;
            j++;
        }
        return count;
    }

    private static int antiDiagonalLine(int[][] mat, int i, int j, int m, int n) {
        int count = 0;
        while (i < m && j >= 0 && mat[i][j] == 1) {
            count++;
            i++;
            j--;
        }
        return count;
    }

