public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int maxLength = 0;

    // Directions: Horizontal, Vertical, Diagonal, Anti-Diagonal
    int[][] directions = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal
        {1, -1}  // Anti-Diagonal
    };

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                for (int[] dir : directions) {
                    maxLength = Math.max(maxLength, findLongestLineFrom(mat, i, j, dir[0], dir[1]));
                }
            }
        }
    }

    return maxLength;
}

private static int findLongestLineFrom(int[][] mat, int x, int y, int deltaX, int deltaY) {
    int count = 0;
    while (x >= 0 && x < mat.length && y >= 0 && y < mat[0].length && mat[x][y] == 1) {
        count++;
        x += deltaX;
        y += deltaY;
    }
    return count;
}
