import java.util.*;

public class SquarePermutations {
    public static int squarePermutations(int[] A) {
        int n = A.length;
        if (n == 0) return 0;

        Map<Integer, List<Integer>> graph = buildGraph(A);
        boolean[] visited = new boolean[n];
        int count = 0;

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                count += dfs(graph, visited, i, 1);
            }
        }

        return count;
    }

    private static Map<Integer, List<Integer>> buildGraph(int[] A) {
        Map<Integer, List<Integer>> graph = new HashMap<>();
        int n = A.length;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i != j && isPerfectSquare(A[i] + A[j])) {
                    graph.computeIfAbsent(i, k -> new ArrayList<>()).add(j);
                    graph.computeIfAbsent(j, k -> new ArrayList<>()).add(i);
                }
            }
        }

        return graph;
    }

    private static boolean isPerfectSquare(int num) {
        int sqrt = (int) Math.sqrt(num);
        return sqrt * sqrt == num;
    }

    private static int dfs(Map<Integer, List<Integer>> graph, boolean[] visited, int node, int count) {
        visited[node] = true;
        count++;

        for (int neighbor : graph.get(node)) {
            if (!visited[neighbor]) {
                count = dfs(graph, visited, neighbor, count);
            }
        }

        return count;
    }

    public static void main(String[] args) {
        System.out.println(squarePermutations(new int[]{1, 17, 8})); // Output: 2
        System.out.println(squarePermutations(new int[]{2, 2, 2})); // Output: 1
    }
}
