import java.util.*;

public class SquarePermutations {
    public static int squarePermutations(int[] A) {
        int n = A.length;
        if (n == 1) {
            return 1;
        }
        List<List<Integer>> permutations = new ArrayList<>();
        permute(A, new boolean[n], new ArrayList<>(), permutations);
        int count = 0;
        for (List<Integer> perm : permutations) {
            if (isSquareArray(perm)) {
                count++;
            }
        }
        return count;
    }

    private static void permute(int[] A, boolean[] used, List<Integer> current, List<List<Integer>> permutations) {
        if (current.size() == A.length) {
            permutations.add(new ArrayList<>(current));
            return;
        }
        for (int i = 0; i < A.length; i++) {
            if (!used[i]) {
                used[i] = true;
                current.add(A[i]);
                permute(A, used, current, permutations);
                current.remove(current.size() - 1);
                used[i] = false;
            }
        }
    }

    private static boolean isSquareArray(List<Integer> A) {
        for (int i = 0; i < A.size() - 1; i++) {
            int sum = A.get(i) + A.get(i + 1);
            if (!isPerfectSquare(sum)) {
                return false;
            }
        }
        return true;
    }

    private static boolean isPerfectSquare(int num) {
        if (num < 0) {
            return false;
        }
        int sqrt = (int) Math.sqrt(num);
        return sqrt * sqrt == num;
    }

    public static void main(String[] args) {
        System.out.println(squarePermutations(new int[]{1, 17, 8})); // Output: 2
        System.out.println(squarePermutations(new int[]{2, 2, 2})); // Output: 1
    }
