public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 1) {
        return 1;
    }

    int count = 0;

    for (int i = 0; i < n; i++) {
        int[] remaining = new int[n - 1];
        int index = 0;
        for (int j = 0; j < n; j++) {
            if (j != i) {
                remaining[index++] = A[j];
            }
        }

        count += permute(remaining, A[i]);
    }

    return count;
}

private static int permute(int[] remaining, int num) {
    int n = remaining.length;
    int count = 0;

    if (n == 0) {
        return 1;
    }

    for (int i = 0; i <= remaining.length; i++) {
        int[] newRemaining = new int[n - 1];
        int newIndex = 0;
        for (int j = 0; j < remaining.length; j++) {
            if (j != i) {
                newRemaining[newIndex++] = remaining[j];
            }
        }

        if (i > 0 && isPerfectSquare(num + remaining[i - 1])) {
            count += permute(newRemaining, remaining[i - 1]);
        }
        if (i < remaining.length && isPerfectSquare(num + remaining[i])) {
            count += permute(newRemaining, remaining[i]);
        }
    }

    return count;
}

private static boolean isPerfectSquare(int x) {
    if (x < 0) {
        return false;
    }
    int sqrt = (int) Math.sqrt(x);
    return sqrt * sqrt == x;
}
