private static void backtracking(int[] A, int index, int[] dp) {
    if (index == A.length - 1) {
        dp[0]++;
        return;
    }

    for (int i = index + 1; i < A.length; i++) {
        if (isPerfectSquare(A[index] + A[i])) {
            swap(A, index + 1, i);
            backtracking(A, index + 1, dp);
            swap(A, index + 1, i);
        }
    }
}

