private static int backtrack(int[] A, boolean[] visited, int currentSum, int start) {
    if (start == A.length) {
        return 1;
    }

    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if (!visited[i]) {
            int nextSum = currentSum + A[i];
            if (isPerfectSquare(nextSum)) {
                visited[i] = true;
                count += backtrack(A, visited, nextSum, start + 1);
                visited[i] = false;
            }
        }
    }

    return count;
}

