public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int length = digits.length;

    // Find the first digit that is smaller than the digit next to it
    for (int i = length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            // Find the smallest digit to the right of 'i' that is larger than digits[i]
            int minIndex = i + 1;
            for (int j = i + 2; j < length; j++) {
                if (digits[j] < digits[minIndex] && digits[j] > digits[i]) {
                    minIndex = j;
                }
            }

            // Swap found digits
            char temp = digits[minIndex];
            digits[minIndex] = digits[i];
            digits[i] = temp;

            // Sort the digits after the current position
            Arrays.sort(digits, i + 1, length);

            return Integer.parseInt(new String(digits));
        }
    }

    // If the digits are in descending order, return -1
    return -1;
}

