    // Find the first digit that is smaller than the digit next to it
    int i;
    for (i = length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such digit is found, return -1 (not possible to get a greater number)
    if (i == -1) {
        return -1;
    }

    // Find the smallest digit on right side of (i) but greater than digits[i]
    int j;
    for (j = length - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
            break;
        }
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Sort the digits after the (i)
    Arrays.sort(digits, i + 1, length);

    // Convert the array of digits back to a number
    return Integer.parseInt(new String(digits));
}

