public static List<String> centerSymmetricNumbers(int n) {
    if (n == 0) return new ArrayList<>();
    if (n == 1) return new ArrayList<>(Arrays.asList("0", "1", "8"));

    char[] pairs = {'0', '1', '8', '6', '9'};
    List<String> result = new ArrayList<>();
    backtrack(result, new char[n], pairs, 0, n - 1);
    return result;
}

private static void backtrack(List<String> result, char[] current, char[] pairs, int left, int right) {
    if (left > right) {
        result.add(new String(current));
        return;
    }
    if (left == right) {
        for (char pair : pairs) {
            if (pair == '6' || pair == '9') continue;
            current[left] = pair;
            result.add(new String(current));
        }
        return;
    }

    for (int i = 0; i < pairs.length; i++) {
        if (i == 2 && left == 0) continue; // Skip '0' for the first position
        current[left] = pairs[i];
        current[right] = pairs[i];
        backtrack(result, current, pairs, left + 1, right - 1);
    }
}

