public class CenterSymmetricNumbers {

    private static final char[][] pairs = {
        {'0', '0'},
        {'1', '1'},
        {'6', '9'},
        {'8', '8'},
        {'9', '6'}
    };

    public static List<String> centerSymmetricNumbers(int n) {
        List<String> result = new ArrayList<>();
        generateCenterSymmetricNumbers(n, n, new char[n], result);
        return result;
    }

    private static void generateCenterSymmetricNumbers(int n, int m, char[] current, List<String> result) {
        if (n == 0) {
            result.add(new String(current));
        } else if (n == 1) {
            for (char[] pair : pairs) {
                if (pair[0] != '0' || m != 1) {
                    current[m / 2] = pair[0];
                    result.add(new String(current));
                }
            }
        } else {
            for (char[] pair : pairs) {
                if (n != m || pair[0] != '0') {
                    current[m - n / 2 - 1] = pair[0];
                    current[m + n / 2] = pair[1];
                    generateCenterSymmetricNumbers(n - 2, m, current, result);
                }
            }
        }
    }

    // Test cases to verify the solution
    public static void main(String[] args) {
        System.out.println(centerSymmetricNumbers(2)); // Output: ["11", "69", "88", "96"]
        System.out.println(centerSymmetricNumbers(1)); // Output: ["0", "1", "8"]
