public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int max_energy = 1;
    int current_energy = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            current_energy++;
            max_energy = Math.max(max_energy, current_energy);
        } else {
            current_energy = 1;
        }
    }

    return max_energy;
}
