public static int minPerfectSquareSum(int n) {
    if (n <= 3) {
        return n;
    }

    int result = n; // Maximum perfect squares is n (e.g., 1+1+...+1)

    for (int i = 1; i <= n; i++) {
        int square = i * i;
        if (square > n) {
            break;
        } else {
            result = Math.min(result, 1 + minPerfectSquareSum(n - square));
        }
    }

    return result;
}

